struct Bits { uint64_t lo=0,hi=0; void add(int x){if(x<64)lo|=1ULL<<x;else hi|=1ULL<<(x-64);} bool has(int x)const{return x<64?((lo>>x)&1):((hi>>(x-64))&1);} void join(Bits b){lo|=b.lo;hi|=b.hi;} bool operator==(Bits b)const{return lo==b.lo&&hi==b.hi;} };
